import js from '@eslint/js'
import globals from 'globals'
import reactHooks from 'eslint-plugin-react-hooks'
import reactRefresh from 'eslint-plugin-react-refresh'
import tseslint from 'typescript-eslint'
import { defineConfig, globalIgnores } from 'eslint/config'

const SIGN_OUT_MESSAGE =
  'Say Sign in / Sign out, never Log in / Log out (Microsoft Writing Style Guide; WCAG 3.2.4).'

export default defineConfig([
  // schema.d.ts is generated by openapi-typescript (see generate:api) — not ours to lint.
  globalIgnores(['dist', 'src/api/schema.d.ts', 'public/mockServiceWorker.js']),
  {
    files: ['**/*.{ts,tsx}'],
    extends: [
      js.configs.recommended,
      tseslint.configs.recommended,
      reactHooks.configs.flat.recommended,
      reactRefresh.configs.vite,
    ],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
    },
    // Hand-written colours are held by src/theme/colourLiterals.test.ts, not by a rule here.
    rules: {
      // The act of ending a session is said one way. White space is required between the two
      // words in all three: without it the route `/bff/auth/logout`, a word such as "logout"
      // and the test stubs' "LOGIN PAGE" would match. It is any run of white space, not one
      // space, because Prettier may break long JSX text between "Log" and "out". A regex
      // literal in a test is not visited, because esquery compares only string values.
      'no-restricted-syntax': [
        'error',
        {
          selector: 'JSXText[value=/\\bLog\\s+(in|out)\\b/i]',
          message: SIGN_OUT_MESSAGE,
        },
        {
          selector: 'Literal[value=/\\bLog\\s+(in|out)\\b/i]',
          message: SIGN_OUT_MESSAGE,
        },
        {
          selector: 'TemplateElement[value.raw=/\\bLog\\s+(in|out)\\b/i]',
          message: SIGN_OUT_MESSAGE,
        },
      ],
    },
  },
])
